ALTER TABLE public.bani_pending_actions DROP CONSTRAINT bani_pending_actions_kind_check;
ALTER TABLE public.bani_pending_actions ADD CONSTRAINT bani_pending_actions_kind_check CHECK(kind IN('mark_closed_days','open_sales_scanner','open_invoice_scanner','people'));
CREATE FUNCTION public.bani_people_claim(t uuid,a uuid,decision text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.bani_pending_actions;BEGIN IF auth.uid() IS NULL OR NOT public.people_access(t,auth.uid()) THEN RAISE EXCEPTION 'People access required';END IF;SELECT * INTO r FROM public.bani_pending_actions WHERE id=a AND tenant_id=t AND user_id=auth.uid() AND kind='people' FOR UPDATE;IF r.id IS NULL OR decision NOT IN('confirm','cancel','change','undo') THEN RAISE EXCEPTION 'People action unavailable';END IF;IF decision='undo' THEN IF r.status<>'confirmed' OR COALESCE((r.payload->'result'->>'undo_available')::boolean,false)=false OR r.payload ? 'undone_at' THEN RAISE EXCEPTION 'Undo unavailable';END IF;ELSE IF r.status<>'pending' OR r.expires_at<now() THEN RAISE EXCEPTION 'Action handled or expired; ask Bani again';END IF;END IF;RETURN to_jsonb(r);END $$;
REVOKE ALL ON FUNCTION public.bani_people_claim(uuid,uuid,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.bani_people_claim(uuid,uuid,text) TO authenticated;
CREATE FUNCTION public.bani_people_finish(t uuid,a uuid,decision text,result jsonb,snapshot jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.bani_pending_actions;BEGIN SELECT * INTO r FROM public.bani_pending_actions WHERE id=a AND tenant_id=t AND user_id=auth.uid() AND kind='people' FOR UPDATE;IF r.id IS NULL OR NOT public.people_access(t,auth.uid()) OR current_setting('bani.people.executing',true) IS DISTINCT FROM a::text THEN RAISE EXCEPTION 'Use the confirmed People action';END IF;UPDATE public.bani_pending_actions SET status=CASE WHEN decision IN('cancel','change') THEN 'cancelled' ELSE 'confirmed' END,resolved_at=now(),payload=payload||jsonb_build_object('result',result,'after',snapshot)||CASE WHEN decision='undo' THEN jsonb_build_object('undone_at',now()) ELSE '{}'::jsonb END WHERE id=a;IF decision IN('confirm','undo') THEN INSERT INTO public.audit_log(tenant_id,user_id,action,entity_type,entity_id,details) VALUES(t,auth.uid(),'bani_people_'||decision,'people',a::text,jsonb_build_object('asked',r.payload->>'instruction','operation',r.payload->>'operation','changes',r.payload,'result',result,'link',r.payload->>'link'));END IF;END $$;
REVOKE ALL ON FUNCTION public.bani_people_finish(uuid,uuid,text,jsonb,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.bani_people_finish(uuid,uuid,text,jsonb,jsonb) TO authenticated;
CREATE FUNCTION public.bani_people_execute(t uuid,a uuid,decision text) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$
DECLARE r jsonb;p jsonb;op text;v uuid;e uuid;w date;c jsonb;current_rows jsonb;weeks jsonb;after_rows jsonb:='{}';result jsonb;cid uuid;rid uuid;balance jsonb;old jsonb;start_day date;end_day date;
BEGIN
r:=public.bani_people_claim(t,a,decision);p:=r->'payload';op:=p->>'operation';v:=NULLIF(p->>'venue_id','')::uuid;e:=NULLIF(p->>'employee_id','')::uuid;w:=NULLIF(p->>'week_start','')::date;
IF decision IN('cancel','change') THEN result:=jsonb_build_object('ok',true,'message',CASE WHEN decision='change' THEN 'Draft cancelled; change the instruction and review again.' ELSE 'Cancelled — nothing changed.' END,'instruction',p->>'instruction');
ELSE
IF NOT public.payroll_manager(t,auth.uid()) THEN RAISE EXCEPTION 'People editing access required';END IF;
IF op IN('rota_edit','rota_send') THEN
IF NOT public.rota_manager(t,v,auth.uid()) THEN RAISE EXCEPTION 'Rota manager access required';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(t::text||v::text,0));
SELECT COALESCE(jsonb_agg(to_jsonb(s) ORDER BY s.id),'[]') INTO current_rows FROM public.hr_shifts s WHERE s.tenant_id=t AND s.shift_date BETWEEN w AND w+6 AND (s.venue_id=v OR s.venue_id IS NULL AND EXISTS(SELECT 1 FROM public.hr_employees x WHERE x.id=s.employee_id AND x.tenant_id=t AND x.venue_id=v));
SELECT COALESCE(jsonb_agg(to_jsonb(q) ORDER BY q.id),'[]') INTO weeks FROM public.hr_rota_weeks q WHERE q.tenant_id=t AND q.venue_id=v AND q.week_start=w;
IF decision='undo' THEN
IF current_rows IS DISTINCT FROM p->'after'->'shifts' OR weeks IS DISTINCT FROM p->'after'->'weeks' THEN RAISE EXCEPTION 'Rota changed since this action; undo is not safe';END IF;
IF EXISTS(SELECT 1 FROM public.hr_payroll h WHERE h.tenant_id=t AND h.employee_id IN(SELECT (x->>'employee_id')::uuid FROM jsonb_array_elements(current_rows||p->'before') x) AND make_date(h.year,h.month,1)<=w+6 AND (make_date(h.year,h.month,1)+interval '1 month')::date>w AND (h.approval_status='approved' OR h.accrual_journal_entry_id IS NOT NULL OR h.payment_status='paid')) THEN RAISE EXCEPTION 'Payroll already approved or posted; undo unavailable';END IF;
DELETE FROM public.hr_shifts WHERE tenant_id=t AND id IN(SELECT (x->>'id')::uuid FROM jsonb_array_elements(current_rows) x) AND id NOT IN(SELECT (x->>'id')::uuid FROM jsonb_array_elements(p->'before') x);
FOR c IN SELECT value FROM jsonb_array_elements(p->'before') LOOP
IF EXISTS(SELECT 1 FROM public.hr_shifts WHERE tenant_id=t AND id=(c->>'id')::uuid) THEN UPDATE public.hr_shifts SET employee_id=(c->>'employee_id')::uuid,venue_id=NULLIF(c->>'venue_id','')::uuid,shift_date=(c->>'shift_date')::date,start_time=(c->>'start_time')::time,end_time=(c->>'end_time')::time,break_minutes=(c->>'break_minutes')::integer,shift_type=c->>'shift_type',role=c->>'role',hours_confirmed_by=NULL,hours_confirmed_at=NULL WHERE tenant_id=t AND id=(c->>'id')::uuid;ELSE INSERT INTO public.hr_shifts SELECT (jsonb_populate_record(NULL::public.hr_shifts,c)).*;END IF;END LOOP;
UPDATE public.hr_rota_weeks SET status='draft',updated_at=now() WHERE tenant_id=t AND venue_id=v AND week_start=w;
result:=jsonb_build_object('ok',true,'message','Undone — rota restored as a draft.','link',p->>'link','undo_available',false);
ELSE
IF current_rows IS DISTINCT FROM (SELECT COALESCE(jsonb_agg(x ORDER BY x->>'id'),'[]') FROM jsonb_array_elements(p->'before') x) OR weeks IS DISTINCT FROM (SELECT COALESCE(jsonb_agg(x ORDER BY x->>'id'),'[]') FROM jsonb_array_elements(p->'week_before') x) THEN RAISE EXCEPTION 'Rota changed; ask Bani for a fresh draft';END IF;
IF op='rota_send' THEN PERFORM public.rota_send(t,v,w);ELSE FOR c IN SELECT value FROM jsonb_array_elements(p->'changes') LOOP IF c ? 'swap_id' THEN PERFORM public.rota_swap(t,(c->>'swap_id')::uuid,(c->>'replacement')::uuid,NULL,true);ELSE PERFORM public.rota_edit(t,v,jsonb_build_array(c));END IF;END LOOP;END IF;
result:=jsonb_build_object('ok',true,'message',CASE WHEN op='rota_send' THEN 'Sent — rota marked sent.' ELSE 'Updated — rota saved as a draft.' END,'link',p->>'link','undo_available',op='rota_edit');END IF;
SELECT jsonb_build_object('shifts',COALESCE((SELECT jsonb_agg(to_jsonb(s) ORDER BY s.id) FROM public.hr_shifts s WHERE s.tenant_id=t AND s.shift_date BETWEEN w AND w+6 AND (s.venue_id=v OR s.venue_id IS NULL AND EXISTS(SELECT 1 FROM public.hr_employees x WHERE x.id=s.employee_id AND x.tenant_id=t AND x.venue_id=v))),'[]'),'weeks',COALESCE((SELECT jsonb_agg(to_jsonb(q) ORDER BY q.id) FROM public.hr_rota_weeks q WHERE q.tenant_id=t AND q.venue_id=v AND q.week_start=w),'[]')) INTO after_rows;
ELSIF op='leave' THEN
start_day:=(p->>'date_from')::date;end_day:=(p->>'date_to')::date;
IF NOT public.rota_manager(t,v,auth.uid()) OR NOT public.people_person_access(t,e,auth.uid()) THEN RAISE EXCEPTION 'Leave manager access required';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(t::text||e::text,1));
SELECT COALESCE(jsonb_agg(to_jsonb(s) ORDER BY s.id),'[]') INTO current_rows FROM public.hr_shifts s WHERE s.tenant_id=t AND s.employee_id=e AND s.shift_date BETWEEN start_day AND end_day;
SELECT COALESCE(jsonb_agg(to_jsonb(b) ORDER BY b.id),'[]') INTO balance FROM public.hr_leave_balances b WHERE b.tenant_id=t AND b.employee_id=e AND b.id IN(SELECT (x->>'id')::uuid FROM jsonb_array_elements(p->'balance_before') x);
IF decision='undo' THEN
IF current_rows IS DISTINCT FROM p->'after'->'shifts' OR balance IS DISTINCT FROM p->'after'->'balances' THEN RAISE EXCEPTION 'Leave or rota changed; undo is not safe';END IF;
rid:=(p->'result'->>'record_id')::uuid;SELECT to_jsonb(l) INTO old FROM public.hr_leave_requests l WHERE l.id=rid AND l.tenant_id=t AND l.employee_id=e FOR UPDATE;
IF old IS DISTINCT FROM p->'after'->'request' THEN RAISE EXCEPTION 'Leave changed; undo is not safe';END IF;
IF EXISTS(SELECT 1 FROM public.hr_payroll h WHERE h.tenant_id=t AND h.employee_id=e AND make_date(h.year,h.month,1)<=end_day AND (make_date(h.year,h.month,1)+interval '1 month')::date>start_day AND (h.approval_status='approved' OR h.accrual_journal_entry_id IS NOT NULL OR h.payment_status='paid')) THEN RAISE EXCEPTION 'Leave is in approved or posted payroll; undo unavailable';END IF;
FOR c IN SELECT value FROM jsonb_array_elements(p->'balance_before') LOOP UPDATE public.hr_leave_balances SET used_days=(c->>'used_days')::numeric,remaining_days=(c->>'remaining_days')::numeric WHERE id=(c->>'id')::uuid AND tenant_id=t;END LOOP;
UPDATE public.hr_leave_requests SET status=CASE WHEN p->>'request_id' IS NOT NULL THEN 'pending' ELSE 'rejected' END,approved_by=NULL,approved_at=NULL WHERE id=rid AND tenant_id=t;
FOR c IN SELECT value FROM jsonb_array_elements(p->'shifts_before') LOOP SELECT venue_id INTO v FROM public.hr_shifts WHERE id=(c->>'id')::uuid AND tenant_id=t;PERFORM public.rota_edit(t,COALESCE(v,(p->>'venue_id')::uuid),jsonb_build_array(c));END LOOP;
result:=jsonb_build_object('ok',true,'message','Undone — leave and its previous rota entries restored.','link',p->>'link','undo_available',false,'record_id',rid);
ELSE
IF current_rows IS DISTINCT FROM (SELECT COALESCE(jsonb_agg(x ORDER BY x->>'id'),'[]') FROM jsonb_array_elements(p->'shifts_before') x) OR balance IS DISTINCT FROM (SELECT COALESCE(jsonb_agg(x ORDER BY x->>'id'),'[]') FROM jsonb_array_elements(p->'balance_before') x) THEN RAISE EXCEPTION 'Leave balance or rota changed; review a fresh draft';END IF;
IF EXISTS(SELECT 1 FROM public.hr_payroll h WHERE h.tenant_id=t AND h.employee_id=e AND make_date(h.year,h.month,1)<=end_day AND (make_date(h.year,h.month,1)+interval '1 month')::date>start_day AND (h.approval_status='approved' OR h.accrual_journal_entry_id IS NOT NULL OR h.payment_status='paid')) THEN RAISE EXCEPTION 'Leave affects approved payroll; review on Payroll first';END IF;
PERFORM public.rota_leave(t,e,p->>'leave_type',start_day,end_day,NULLIF(p->>'request_id','')::uuid,true);
SELECT id INTO rid FROM public.hr_leave_requests WHERE tenant_id=t AND employee_id=e AND start_date=start_day AND end_date=end_day AND status='approved' ORDER BY approved_at DESC LIMIT 1;
result:=jsonb_build_object('ok',true,'message','Recorded — leave approved and rota updated.','link',p->>'link','record_id',rid,'undo_available',true);END IF;
SELECT jsonb_build_object('shifts',COALESCE((SELECT jsonb_agg(to_jsonb(s) ORDER BY s.id) FROM public.hr_shifts s WHERE s.tenant_id=t AND s.employee_id=e AND s.shift_date BETWEEN start_day AND end_day),'[]'),'balances',COALESCE((SELECT jsonb_agg(to_jsonb(b) ORDER BY b.id) FROM public.hr_leave_balances b WHERE b.tenant_id=t AND b.employee_id=e AND b.id IN(SELECT (x->>'id')::uuid FROM jsonb_array_elements(p->'balance_before') x)),'[]'),'request',(SELECT to_jsonb(l) FROM public.hr_leave_requests l WHERE l.id=rid AND l.tenant_id=t)) INTO after_rows;
ELSIF decision='undo' THEN RAISE EXCEPTION 'Undo unavailable for this action';
ELSIF op='team_change' THEN
IF e IS NOT NULL AND (SELECT to_jsonb(x) FROM public.hr_employees x WHERE x.id=e AND x.tenant_id=t) IS DISTINCT FROM p->'person_before' THEN RAISE EXCEPTION 'Person changed; review a fresh draft';END IF;
cid:=public.confirm_people_change(t,e,(p->>'effective_date')::date,p->'values',p->>'change_type',NULL);SELECT status INTO op FROM public.hr_people_changes WHERE id=cid AND tenant_id=t;
result:=jsonb_build_object('ok',true,'message',CASE WHEN op='approved' THEN 'Recorded — dated Team change applied.' ELSE 'Submitted — Team change awaits owner approval.' END,'link',p->>'link','record_id',cid,'undo_available',false);
ELSIF op='team_approve' THEN
IF (SELECT to_jsonb(x) FROM public.hr_people_changes x WHERE x.id=(p->>'change_id')::uuid AND x.tenant_id=t) IS DISTINCT FROM p->'change_before' THEN RAISE EXCEPTION 'Team request changed; review again';END IF;
PERFORM public.approve_people_change((p->>'change_id')::uuid,true);result:=jsonb_build_object('ok',true,'message','Approved — dated Team change recorded.','link',p->>'link','record_id',p->>'change_id','undo_available',false);
ELSIF op IN('payroll_prepare','payroll_instruction') THEN
SELECT COALESCE(jsonb_agg(to_jsonb(q) ORDER BY q.id),'[]') INTO current_rows FROM public.hr_payroll_months q WHERE q.tenant_id=t AND q.year=(p->>'year')::integer AND q.month=(p->>'month')::integer;
IF current_rows IS DISTINCT FROM (SELECT COALESCE(jsonb_agg(x ORDER BY x->>'id'),'[]') FROM jsonb_array_elements(p->'period_before') x) THEN RAISE EXCEPTION 'Payroll month changed; review a fresh draft';END IF;
IF op='payroll_prepare' THEN IF public.payroll_preview(t,(p->>'year')::integer,(p->>'month')::integer) IS DISTINCT FROM p->'preview_before' THEN RAISE EXCEPTION 'Payroll inputs changed; review a fresh draft';END IF;PERFORM public.payroll_prepare(t,(p->>'year')::integer,(p->>'month')::integer);result:=jsonb_build_object('ok',true,'message','Prepared — month calculated; missing inputs remain flagged.','link',p->>'link','undo_available',false);
ELSE PERFORM public.payroll_override_batch(t,p->'changes',(p->>'repeating')::boolean,(p->>'revision')::integer);result:=jsonb_build_object('ok',true,'message','Recorded — exact pay instruction applied.','link',p->>'link','undo_available',false);END IF;
ELSE RAISE EXCEPTION 'Unsupported People operation; payroll approval is page-only';END IF;END IF;
PERFORM set_config('bani.people.executing',a::text,true);PERFORM public.bani_people_finish(t,a,decision,result,after_rows);PERFORM set_config('bani.people.executing','',true);RETURN result;END $$;
REVOKE ALL ON FUNCTION public.bani_people_execute(uuid,uuid,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.bani_people_execute(uuid,uuid,text) TO authenticated;